import { t } from '../../language/index.js';
import { IMAGE_OPERATIONS, VIDEO_OPERATIONS } from '@/types/media-tool';
import { showConfirmDialog } from 'vant';
import { downloadImage, downloadVideo } from '@/utils/util.js';
import { showMessageError, showMessageSuccess } from '@/utils/mobile-ui-feedback.js';

/**
 * 移动端媒体操作处理器
 * 支持两种模式：
 * 1. 按钮Loading模式（默认）：点击确认 → 按钮显示loading → 操作完成 → 关闭弹窗
 * 2. 直接关闭模式：点击确认 → 直接关闭弹窗
 */

/**
 * 处理移动端媒体操作
 * @param {Object} action - 操作对象 { type: string }
 * @param {Object} mediaData - 媒体数据 { url, name, etc. }
 * @param {Object} options - 配置选项
 * @param {boolean} options.directClose - 是否直接关闭模式（默认false，即使用按钮loading）
 * @param {Function} options.onSuccess - 成功回调
 * @param {Function} options.onError - 错误回调
 * @param {Function} options.onCancel - 取消回调
 * @returns {Promise}
 */
export function handleMobileMediaAction(action, mediaData, options = {}) {
    const { 
        directClose = false,
        onSuccess, 
        onError, 
        onCancel
    } = options;

    const { type } = action;
    const config = getActionConfig(type);
    
    if (!config) {
        console.warn('Unknown action type:', type);
        return Promise.reject(new Error('Unknown action type'));
    }

    // 根据模式选择处理方式
    if (directClose) {
        return handleDirectCloseMode(type, config, mediaData, options);
    } else {
        return handleButtonLoadingMode(type, config, mediaData, options);
    }
}

/**
 * 按钮Loading模式：确认按钮显示loading
 */
function handleButtonLoadingMode(type, config, mediaData, options) {
    return showConfirmDialog({
        title: config.title,
        message: config.message,
        confirmButtonText: t('mobileConfirmAction'),
        cancelButtonText: t('mobileCancelAction'),
        confirmButtonColor: '#007AFF',
        cancelButtonColor: '#007AFF',
        beforeClose: (action) => {
            if (action === 'confirm') {
                // 返回Promise，按钮会显示loading直到Promise resolve
                return executeOperation(type, mediaData, options)
                    .then(() => {
                        // 操作成功，允许关闭弹窗
                        return true;
                    })
                    .catch((error) => {
                        // 操作失败，阻止关闭弹窗（可重试）
                        console.error('Operation failed, keeping dialog open for retry:', error);
                        return false;
                    });
            }
            return true; // 取消操作，直接关闭
        }
    }).then(() => {
        return { success: true, type, mode: 'buttonLoading' };
    }).catch((error) => {
        if (error === 'cancel') {
            if (options.onCancel) {
                options.onCancel(type);
            }
            return Promise.reject({ cancelled: true, type, mode: 'buttonLoading' });
        }
        return Promise.reject({ failed: true, type, error, mode: 'buttonLoading' });
    });
}

/**
 * 直接关闭模式：点击确认直接关闭弹窗
 */
function handleDirectCloseMode(type, config, mediaData, options) {
    return showConfirmDialog({
        title: config.title,
        message: config.message,
        confirmButtonText: t('mobileConfirmAction'),
        cancelButtonText: t('mobileCancelAction'),
        confirmButtonColor: '#007AFF',
        cancelButtonColor: '#007AFF'
    }).then(async () => {
        // 特殊处理下载操作
        if (type === IMAGE_OPERATIONS.DOWNLOAD || type === VIDEO_OPERATIONS.DOWNLOAD) {
            try {
                // 执行下载操作
                await performOperation(type, mediaData);
                // 成功回调
                if (options.onSuccess) {
                    options.onSuccess(type);
                }
            } catch (error) {
                // 错误回调
                if (options.onError) {
                    options.onError(type, error);
                }
                
                // 即使下载失败也返回成功，因为弹窗已关闭
            }
        } else {
            // 非下载操作，执行操作的回调
            if (options.onSuccess) {
                options.onSuccess(type);
            }
        }
        
        return { success: true, type, mode: 'directClose' };
    }).catch((error) => {
        if (error === 'cancel') {
            if (options.onCancel) {
                options.onCancel(type);
            }
            return Promise.reject({ cancelled: true, type, mode: 'directClose' });
        }
        return Promise.reject({ failed: true, type, error, mode: 'directClose' });
    });
}

/**
 * 执行操作（仅按钮Loading模式使用）
 */
async function executeOperation(type, mediaData, options) {
    try {
        let result = await performOperation(type, mediaData);        
        // 成功回调
        if (options.onSuccess) {
            options.onSuccess(type, result);
        }
        
        return; // 返回成功，让弹窗关闭
        
    } catch (error) {
        console.error(`Operation failed for ${type}:`, error);
        
        // 错误回调
        if (options.onError) {
            options.onError(type, error);
        }
        
        throw error; // 抛出错误，阻止弹窗关闭
    }
}

/**
 * 执行具体的操作
 */
async function performOperation(type, mediaData) {
    if (type === IMAGE_OPERATIONS.DOWNLOAD || type === VIDEO_OPERATIONS.DOWNLOAD) {
        // 下载操作 - 真实功能
        if (type === IMAGE_OPERATIONS.DOWNLOAD) {
            return await downloadImage(mediaData.url);
        } else if (type === VIDEO_OPERATIONS.DOWNLOAD) {
            return await downloadVideo(mediaData.url);
        }
    } else {
        // 其他操作 - 模拟处理
        return await simulateProcessing(type, mediaData);
    }
}

/**
 * 模拟其他操作的处理过程
 */
async function simulateProcessing(type, mediaData) {
    // 模拟1-3秒的处理时间
    const processingTime = 1000 + Math.random() * 2000;
    await new Promise(resolve => setTimeout(resolve, processingTime));
    
    // 模拟100%成功率（测试环境）
    return {
        success: true,
        type,
        originalData: mediaData,
        processedAt: new Date().toISOString(),
        note: 'This is a simulated result. Implement actual processing logic here.'
    };
}

/**
 * 获取操作配置
 */
function getActionConfig(type) {
    const configs = {
        // 图片操作
        [IMAGE_OPERATIONS.DOWNLOAD]: {
            title: t('mobileDownloadImage'),
            message: t('mobileDownloadImageDesc')
        },
        [IMAGE_OPERATIONS.ENHANCE]: {
            title: t('mobileEnhanceImage'),
            message: t('mobileEnhanceImageDesc')
        },
        [IMAGE_OPERATIONS.EDIT]: {
            title: t('mobileEditImage'),
            message: t('mobileEditImageDesc')
        },
        [IMAGE_OPERATIONS.ENLARGE]: {
            title: t('mobileUpscaleImage'),
            message: t('mobileUpscaleImageDesc')
        },
        [IMAGE_OPERATIONS.TO_VIDEO]: {
            title: t('mobileConvertToVideo'),
            message: t('mobileConvertToVideoDesc')
        },

        // 视频操作
        [VIDEO_OPERATIONS.DOWNLOAD]: {
            title: t('mobileDownloadVideo'),
            message: t('mobileDownloadVideoDesc')
        },
        [VIDEO_OPERATIONS.UPSCALE]: {
            title: t('mobileUpscaleVideo'),
            message: t('mobileUpscaleVideoDesc')
        },
        [VIDEO_OPERATIONS.SOUNDTRACK]: {
            title: t('mobileAddSoundtrack'),
            message: t('mobileAddSoundtrackDesc')
        },
        [VIDEO_OPERATIONS.VIDEO_STYLE]: {
            title: t('mobileChangeStyle'),
            message: t('mobileChangeStyleDesc')
        },
        [VIDEO_OPERATIONS.FRAME_FILLING]: {
            title: t('mobileFrameFiller'),
            message: t('mobileFrameFillerDesc')
        }
    };

    return configs[type] || null;
}